    price DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (bar, beer),
    FOREIGN KEY (bar) REFERENCES Bar(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

CREATE TABLE Likes (
    drinker VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    PRIMARY KEY (drinker, beer),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

counterexample:
INSERT INTO Drinker (name, address) VALUES ('Bob', '123 Main St');

INSERT INTO Bar (name, address) VALUES ('Bar1', '456 High St');

INSERT INTO Beer (name, brewer) VALUES ('Bud', 'Budweiser');

INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Bob', 'Bar1', 3);

INSERT INTO Serves (bar, beer, price) VALUES ('Bar1', 'Bud', 5.00);

-- Bob does not have any entry in Likes, which triggers the difference in behavior between Q1 and Q2.

