counterexample:
-- Inserting test data for the counterexample

-- Insert a drinker D1 who does NOT frequent any bar
INSERT INTO Drinker (name, address) VALUES ('D1', 'addrD1');

-- Insert a beer that D1 likes
INSERT INTO Beer (name, brewer) VALUES ('B1', 'brew1');

-- Insert a Bar (required for FK constraints in other tables, though not used by D1 in frequents)
INSERT INTO Bar (name, address) VALUES ('Bar1', 'addrBar1');

-- Insert a Likes record for D1 so that D1 has a nonzero count in likes
INSERT INTO Likes (drinker, beer) VALUES ('D1', 'B1');

-- Note: Do NOT insert any record into Frequents for D1 so that D1 has no frequented bars

-- (Optionally, you can add records in Serves for Bar1 if needed for other tests, but here they are not referenced by D1)

