CREATE TABLE Bar (
    name VARCHAR NOT NULL,
    address VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Beer (
    name VARCHAR NOT NULL,
    brewer VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Drinker (
    name VARCHAR NOT NULL,
    address VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Frequents (
    drinker VARCHAR NOT NULL,
    bar VARCHAR NOT NULL,
    times_a_week SMALLINT NOT NULL,
    PRIMARY KEY (drinker, bar),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (bar) REFERENCES Bar(name)
);

CREATE TABLE Serves (
    bar VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    price DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (bar, beer),
    FOREIGN KEY (bar) REFERENCES Bar(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

CREATE TABLE Likes (
    drinker VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    PRIMARY KEY (drinker, beer),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

counterexample:
INSERT INTO Bar (name, address) VALUES ('bar1', 'Address1');
INSERT INTO Bar (name, address) VALUES ('bar2', 'Address2');

INSERT INTO Beer (name, brewer) VALUES ('beer1', 'Brewer1');

INSERT INTO Drinker (name, address) VALUES ('Bob', 'AddressBob');
INSERT INTO Drinker (name, address) VALUES ('Bill', 'AddressBill');

-- Bob frequents bar1, Bill frequents bar2
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Bob', 'bar1', 3);
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Bill', 'bar2', 2);

-- beer1 is served in both bars with different prices
INSERT INTO Serves (bar, beer, price) VALUES ('bar1', 'beer1', 5.00);
INSERT INTO Serves (bar, beer, price) VALUES ('bar2', 'beer1', 7.00);

-- Only Bill likes beer1; Bob does not
INSERT INTO Likes (drinker, beer) VALUES ('Bill', 'beer1');

