counterexample:
-- Insert a bar with both frequents and serves (will be returned by both Q1 and Q2)
INSERT INTO Bar (name, address) VALUES ('B1', 'address1');

-- Insert a bar with a serves record but without a frequents record (will be returned by Q1 only)
INSERT INTO Bar (name, address) VALUES ('B2', 'address2');

-- Insert a Beer record (needed for the Serves table)
INSERT INTO Beer (name, brewer) VALUES ('beer1', 'brewerA');

-- Insert a Serves record for both bars
INSERT INTO Serves (bar, beer, price) VALUES ('B1', 'beer1', 4.00);
INSERT INTO Serves (bar, beer, price) VALUES ('B2', 'beer1', 6.00);

-- Insert a Drinker record (needed for the Frequents table)
INSERT INTO Drinker (name, address) VALUES ('d1', 'd1_address');

-- Insert a Frequents record for B1 only
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('d1', 'B1', 3);

